// ===== Unit Loss / Deterrent Estimates =====
// Based on ≥10-unit new-construction projects inside MIN — the category MIN regulates.
//
// HEADLINE = deterred new-construction units against a market-strength-MATCHED
// citywide control (METHODOLOGY.md §2). This supersedes the earlier within-district
// trimmed-mean estimate (~3,000), which the same methodology now classifies as an
// upper bound contaminated by control selection (MIN blankets the strong-market
// submarkets; the parcels left outside MIN within CD3/CD7 are weaker-market leftovers).

export const UNIT_LOSS = {
  lostPermits: 64,
  /**
   * HEADLINE: total housing units deterred vs a market-strength-matched control,
   * counting new construction AND conversions (methodology §2). The new-construction
   * core is stable (~450, a +16–23 pp DiD); the conversion channel adds the rest but
   * is spikier (dominated by a couple of mega-conversions), so we cite the total as a
   * range. This SUPERSEDES the within-district permit×size method (see below), which
   * runs far higher because its control is the weaker-market parcels left outside MIN.
   */
  headline: 1200,
  headlineLabel: "~1,200",
  deterredTotalRange: { low: 1000, high: 1400, label: "1,000–1,400" },
  /** Stable new-construction-only component — the matched-control DiD figure */
  newConstructionUnits: 450,
  newConstructionLabel: "~450",
  matchedControlDid: { low: 16, high: 23, label: "+16 to +23 pp" },
  /** Within-district permit×size method — SUPERSEDED; control selection inflates it */
  withinDistrictUpperBound: { low: 1920, high: 3866, label: "~1,900–3,900" },
  estimators: {
    mean: { avgUnits: 60.4, lostUnits: 3866, label: "Mean (within-district, superseded)" },
    trimmedMean: { avgUnits: 46.6, lostUnits: 2983, label: "Trimmed mean (within-district, superseded)" },
    median: { avgUnits: 30.0, lostUnits: 1920, label: "Median (within-district, superseded)" },
  },
  /** Affordable units deterred ≈ 20% of the total deterred (MIN covers conversions too) */
  affordableUnitsLost: 240,
  affordableUnitsLostLabel: "~240",
  /** What MIN actually produced — City of Philadelphia 2025 Mixed Income Housing Program Report */
  affordableUnitsProduced: 19,
  producedSource: "City of Philadelphia 2025 Mixed Income Housing Program Report (Aug 2026)",
  /** Distribution context (within-district large projects) */
  distribution: {
    p25: 17,
    p50: 30,
    p75: 83,
    max: 405,
    projectsOver100: 26,
  },
};

